using System;
using System.Collections.Generic;
using System.Linq;
using System.Linq.Expressions;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;

// ===================== 领域层 =====================

// 领域事件标记接口
public interface IDomainEvent { }

// 聚合根基类
public abstract class AggregateRoot
{
    public int Id { get; protected set; }
    private readonly List<IDomainEvent> _domainEvents = new();
    public IReadOnlyList<IDomainEvent> DomainEvents => _domainEvents;

    protected void AddDomainEvent(IDomainEvent domainEvent)
        => _domainEvents.Add(domainEvent);

    public void ClearDomainEvents()
        => _domainEvents.Clear();
}

// Order 聚合根
public class Order : AggregateRoot
{
    public int UserId { get; private set; }
    public decimal TotalAmount { get; private set; }
    public OrderStatus Status { get; private set; }
    private readonly List<OrderItem> _items = new();
    public IReadOnlyList<OrderItem> Items => _items;

    public static Order Create(int userId)
    {
        return new Order { UserId = userId, Status = OrderStatus.Pending };
    }

    public void AddItem(string productName, decimal price, int quantity)
    {
        if (quantity <= 0) throw new ArgumentException("数量必须大于零");
        _items.Add(new OrderItem(productName, price, quantity));
        TotalAmount += price * quantity;
        AddDomainEvent(new OrderItemAddedEvent(Id, productName, quantity));
    }

    public void Submit()
    {
        if (Status != OrderStatus.Pending)
            throw new InvalidOperationException("只有待处理订单可以提交");
        if (_items.Count == 0)
            throw new InvalidOperationException("空订单不能提交");
        Status = OrderStatus.Submitted;
        AddDomainEvent(new OrderSubmittedEvent(Id));
    }
}

public class OrderItem
{
    public int Id { get; set; }
    public string ProductName { get; private set; }
    public decimal Price { get; private set; }
    public int Quantity { get; private set; }
    public int OrderId { get; set; }

    private OrderItem() { }
    internal OrderItem(string productName, decimal price, int quantity)
    {
        ProductName = productName;
        Price = price;
        Quantity = quantity;
    }
}

public enum OrderStatus { Pending, Submitted, Processing, Completed, Cancelled }

public class OrderSubmittedEvent : IDomainEvent
{
    public int OrderId { get; }
    public DateTime OccurredOn { get; }
    public OrderSubmittedEvent(int orderId)
    {
        OrderId = orderId;
        OccurredOn = DateTime.UtcNow;
    }
}

public class OrderItemAddedEvent : IDomainEvent
{
    public int OrderId { get; }
    public string ProductName { get; }
    public int Quantity { get; }
    public DateTime OccurredOn { get; }
    public OrderItemAddedEvent(int orderId, string productName, int quantity)
    {
        OrderId = orderId;
        ProductName = productName;
        Quantity = quantity;
        OccurredOn = DateTime.UtcNow;
    }
}

// 领域仓储接口（只为聚合根定义）
public interface IOrderRepository
{
    Task<Order?> GetByIdAsync(int orderId);
    Task<Order?> GetByIdWithItemsAsync(int orderId);
    Task<List<Order>> GetPendingOrdersAsync();
    Task AddAsync(Order order);
}

// ===================== 基础设施层 =====================

// 仓储实现
public class OrderRepository : IOrderRepository
{
    private readonly AppDbContext _context;
    public OrderRepository(AppDbContext context) => _context = context;

    public async Task<Order?> GetByIdAsync(int orderId)
        => await _context.Orders.FindAsync(orderId);

    public async Task<Order?> GetByIdWithItemsAsync(int orderId)
        => await _context.Orders
            .Include(o => o.Items)
            .FirstOrDefaultAsync(o => o.Id == orderId);

    public async Task<List<Order>> GetPendingOrdersAsync()
        => await _context.Orders
            .Where(o => o.Status == OrderStatus.Pending)
            .OrderBy(o => o.Id)
            .ToListAsync();

    public async Task AddAsync(Order order)
        => await _context.Orders.AddAsync(order);
}

// 领域事件 Dispatcher
public interface IDomainEventDispatcher
{
    Task DispatchAsync(IEnumerable<IDomainEvent> events);
}

public class DomainEventDispatcher : IDomainEventDispatcher
{
    private readonly IServiceProvider _sp;
    public DomainEventDispatcher(IServiceProvider sp) => _sp = sp;

    public async Task DispatchAsync(IEnumerable<IDomainEvent> events)
    {
        foreach (var domainEvent in events)
        {
            var handlerType = typeof(IDomainEventHandler<>).MakeGenericType(domainEvent.GetType());
            var handlers = _sp.GetServices(handlerType);
            foreach (var handler in handlers)
            {
                var method = handlerType.GetMethod("HandleAsync");
                await (Task)method!.Invoke(handler, new object[] { domainEvent });
            }
        }
    }
}

public interface IDomainEventHandler<in TEvent> where TEvent : IDomainEvent
{
    Task HandleAsync(TEvent domainEvent);
}

public class OrderSubmittedEmailHandler : IDomainEventHandler<OrderSubmittedEvent>
{
    public async Task HandleAsync(OrderSubmittedEvent domainEvent)
    {
        // 模拟发邮件
        Console.WriteLine($"[邮件] 订单 {domainEvent.OrderId} 已提交，发送确认邮件");
        await Task.CompletedTask;
    }
}

// Unit of Work
public interface IUnitOfWork : IDisposable
{
    IOrderRepository Orders { get; }
    Task<int> SaveChangesAsync(CancellationToken ct = default);
}

public class UnitOfWork : IUnitOfWork
{
    private readonly AppDbContext _context;
    private readonly IDomainEventDispatcher _dispatcher;
    private IOrderRepository _orders;

    public UnitOfWork(AppDbContext context, IDomainEventDispatcher dispatcher)
    {
        _context = context;
        _dispatcher = dispatcher;
    }

    public IOrderRepository Orders
        => _orders ??= new OrderRepository(_context);

    public async Task<int> SaveChangesAsync(CancellationToken ct = default)
    {
        // 收集所有聚合根的领域事件
        var entries = _context.ChangeTracker.Entries<AggregateRoot>()
            .Where(e => e.Entity.DomainEvents.Any())
            .ToList();

        var allEvents = entries
            .SelectMany(e => e.Entity.DomainEvents)
            .ToList();

        // 提交前 dispatch 本地事件（同事务内）
        await _dispatcher.DispatchAsync(allEvents);

        // 清除事件，避免重复 dispatch
        entries.ForEach(e => e.Entity.ClearDomainEvents());

        // 持久化
        var result = await _context.SaveChangesAsync(ct);

        // 提交后可 dispatch 进程外事件（消息队列等），此处省略
        return result;
    }

    public void Dispose() => _context.Dispose();
}

// ===================== 基础设施配置 =====================

public class User
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
    public int Points { get; set; }
}

public class AppDbContext : DbContext
{
    public DbSet<User> Users => Set<User>();
    public DbSet<Order> Orders => Set<Order>();
    public DbSet<OrderItem> OrderItems => Set<OrderItem>();

    public AppDbContext(DbContextOptions<AppDbContext> options) : base(options) { }

    protected override void OnModelCreating(ModelBuilder builder)
    {
        builder.Entity<Order>(b =>
        {
            b.Ignore(o => o.DomainEvents);
            b.HasMany(o => o.Items)
             .WithOne()
             .HasForeignKey(i => i.OrderId);
        });
    }
}

// DI 注册
public static class RepositoryUowExtensions
{
    public static IServiceCollection AddRepositoryUoW(this IServiceCollection services)
    {
        services.AddScoped<IUnitOfWork, UnitOfWork>();
        services.AddScoped<IDomainEventDispatcher, DomainEventDispatcher>();
        services.AddScoped<IDomainEventHandler<OrderSubmittedEvent>, OrderSubmittedEmailHandler>();
        return services;
    }
}

// ===================== 应用层使用示例 =====================

public class OrderService
{
    private readonly IUnitOfWork _uow;
    public OrderService(IUnitOfWork uow) => _uow = uow;

    public async Task<Order> CreateAndSubmitOrderAsync(int userId)
    {
        var order = Order.Create(userId);
        order.AddItem("键盘", 299.99m, 1);
        order.AddItem("鼠标", 99.99m, 2);

        await _uow.Orders.AddAsync(order);
        order.Submit(); // 产生 OrderSubmittedEvent

        await _uow.SaveChangesAsync(); // 事务提交 + 事件 dispatch
        return order;
    }
}
